const R=6371000,rad=Math.PI/180;
export function haversine(a,b){const dLat=(b[1]-a[1])*rad,dLon=(b[0]-a[0])*rad;return 2*R*Math.asin(Math.min(1,Math.sqrt(Math.sin(dLat/2)**2+Math.cos(a[1]*rad)*Math.cos(b[1]*rad)*Math.sin(dLon/2)**2)));}
export function segmentDistance(p,a,b){const c=Math.cos(p[1]*rad),x=(a[0]-p[0])*rad*R*c,y=(a[1]-p[1])*rad*R,dx=(b[0]-a[0])*rad*R*c,dy=(b[1]-a[1])*rad*R;const t=Math.max(0,Math.min(1,-(x*dx+y*dy)/(dx*dx+dy*dy||1)));return {distance:Math.hypot(x+t*dx,y+t*dy),t};}
export function routePosition(p,coords){let best=Infinity,along=0,total=0;for(let i=1;i<coords.length;i++){const d=segmentDistance(p,coords[i-1],coords[i]),length=haversine(coords[i-1],coords[i]);if(d.distance<best){best=d.distance;along=total+d.t*length;}total+=length;}return {distance:best,along};}
export function simplify(coords,tolerance=100){if(coords.length<3)return coords;const keep=new Set([0,coords.length-1]),stack=[[0,coords.length-1]];while(stack.length){const [a,b]=stack.pop();let max=tolerance,index=-1;for(let i=a+1;i<b;i++){const d=segmentDistance(coords[i],coords[a],coords[b]).distance;if(d>max){max=d;index=i;}}if(index>=0){keep.add(index);stack.push([a,index],[index,b]);}}return [...keep].sort((a,b)=>a-b).map(i=>coords[i]);}
export function hotelQuery(coords,radius){const line=simplify(coords,100).map(p=>`${p[1].toFixed(6)},${p[0].toFixed(6)}`).join(',');return `[out:json][timeout:45];nwr["tourism"="hotel"](around:${radius+150},${line});out center tags;`;}
export function extractHotels(elements,coords,radius){const hotels=[];for(const e of elements){const lon=e.lon??e.center?.lon,lat=e.lat??e.center?.lat;if(!Number.isFinite(lon)||!Number.isFinite(lat))continue;const pos=routePosition([lon,lat],coords);if(pos.distance>radius)continue;const tags=e.tags??{},name=tags.name??tags['name:nb']??'Hotell uten registrert navn';if(hotels.some(h=>h.name===name&&haversine(h.coords,[lon,lat])<120))continue;hotels.push({id:`${e.type}/${e.id}`,name,coords:[lon,lat],tags,...pos});}return hotels.sort((a,b)=>a.along-b.along||a.distance-b.distance);}
export const normalizePlace=name=>String(name??'').normalize('NFKC').trim().toLocaleLowerCase('nb-NO');
export function inRing(point,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if(segmentDistance(point,a,b).distance<.1)return true;if((a[1]>point[1])!==(b[1]>point[1])&&point[0]<(b[0]-a[0])*(point[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
export function inSettlement(point,place){if(!place)return false;const [w,s,e,n]=place.bbox,margin=.001;if(point[0]<w-margin||point[0]>e+margin||point[1]<s-margin||point[1]>n+margin)return false;return place.rings.some(ring=>inRing(point,ring)||ring.some((p,i)=>i>0&&segmentDistance(point,ring[i-1],p).distance<=25));}
export function findStartSettlement(from,places){const matches=places.filter(p=>inSettlement(from.coords,p));return matches.find(p=>normalizePlace(p.name)===normalizePlace(from.name))??matches.sort((a,b)=>b.population-a.population)[0]??null;}
export function excludeStartHotels(hotels,from,settlement){return hotels.filter(h=>{const city=h.tags?.['addr:city'],place=h.tags?.['addr:place'];return ![city,place].some(name=>name&&normalizePlace(name)===normalizePlace(from.name))&&!inSettlement(h.coords,settlement);});}
export function excludeStartResults(results,origin){return results.filter(place=>haversine(origin,place.coords)>3000+1e-6);}
